def detect_language(text: str) -> str:
    """Detect the dominant language from script ranges and stopword frequency."""
    sample = text[:4000]
    counts = {
        "zh": len(re.findall(r"[\u4e00-\u9fff]", sample)),
        "hi": len(re.findall(r"[\u0900-\u097f]", sample)),
        "ar": len(re.findall(r"[\u0600-\u06ff]", sample)),
    }
    script, n = max(counts.items(), key=lambda kv: kv[1])
    latin = len(re.findall(r"[A-Za-zÀ-ÿ]", sample))
    if n > 40 or (n >= 6 and n >= 0.25 * latin):
        return script
    words = re.findall(r"[a-zà-ÿñ]+", sample.lower())
    scores = {lang: sum(1 for w in words if w in STOPWORDS[lang]) for lang in ("en", "fr", "es")}
    return max(scores, key=scores.get) if any(scores.values()) else "en"
